import { readFile, writeFile } from "node:fs/promises";
import { join } from "node:path";

const args = process.argv.slice(2);
const mode = process.env.SKILLBENCH_FAKE_OPENCODE_MODE ?? "success";

if (args.includes("--version")) {
  process.stdout.write(`${mode === "unsupported-version" ? "1.17.9" : "1.18.12"}\n`);
  process.exit(0);
}

if (args[0] === "session" && args[1] === "list") {
  try {
    const session = JSON.parse(
      await readFile(join(process.cwd(), ".opencode", "fake-session.json"), "utf8"),
    ) as { id: string; title: string };
    process.stdout.write(`${JSON.stringify([session])}\n`);
  } catch {
    process.stdout.write("[]\n");
  }
  process.exit(0);
}

if (args[0] === "session" && args[1] === "delete") {
  if (mode === "cleanup-failure") {
    process.stderr.write("fake cleanup failure\n");
    process.exit(9);
  }
  await writeFile(join(process.cwd(), ".opencode", "deleted-session.txt"), args[2] ?? "");
  process.exit(0);
}

if (args[0] !== "run") {
  process.stderr.write("expected run\n");
  process.exit(2);
}

const titleIndex = args.indexOf("--title");
const title = titleIndex === -1 ? "missing" : (args[titleIndex + 1] ?? "missing");
await writeFile(
  join(process.cwd(), ".opencode", "fake-session.json"),
  `${JSON.stringify({ id: "ses_fake", title })}\n`,
);
await writeFile(join(process.cwd(), "argv.json"), `${JSON.stringify(args)}\n`);

const emit = (event: unknown) => process.stdout.write(`${JSON.stringify(event)}\n`);
emit({ type: "step_start", sessionID: "ses_fake", part: { type: "step-start" } });

if (mode === "timeout" || mode === "cancel") {
  setInterval(() => undefined, 1_000);
  await new Promise(() => undefined);
}

if (mode === "nonzero") {
  emit({
    type: "error",
    sessionID: "ses_fake",
    error: { name: "ProviderError", data: { message: "fake provider failure" } },
  });
  process.exit(7);
}

if (mode === "invalid") {
  process.stdout.write("not-json\n");
  process.exit(0);
}

if (mode !== "missing-text") {
  await writeFile(join(process.cwd(), "generated.txt"), "generated by fake OpenCode\n");
  emit({
    type: "text",
    sessionID: "ses_fake",
    part: { type: "text", text: "FAKE_OPENCODE_OK", time: { end: Date.now() } },
  });
}
emit({
  type: "step_finish",
  sessionID: "ses_fake",
  part: {
    type: "step-finish",
    tokens: { input: 19, output: 7 },
    cost: 0.012,
  },
});

if (mode === "large") process.stderr.write("x".repeat(16_384));
